public interface ObjectDefaultActionsMixin {

	PluginTool getTool();

	DebuggerCoordinates getCurrent();

	void activatePath(KeyPath path);

	void toggleObject(TraceObject @object) {
		if (!getCurrent().isAliveAndPresent()) {
			return;
		}
		Target target = getCurrent().getTarget();
		Map<string, ActionEntry> actions = target.collectActions(ActionName.TOGGLE,
			new DebuggerSingleObjectPathActionContext(@object.getCanonicalPath()),
			ObjectArgumentPolicy.CONTEXT_ONLY);
		ActionEntry action = actions.values()
				.stream()
				.filter(e => !e.requiresPrompt())
				.sorted(Comparator.comparing(e => -e.specificity()))
				.findFirst()
				.orElse(null);
		if (action == null) {
			Msg.error(this, "No suitable toggle action for " + @object);
			return;
		}
		TargetActionTask.runAction(getTool(), "Toggle", action);
	}

	void goToAddress(DebuggerListingService listingService, Address address) {
		ProgramLocation loc = new ProgramLocation(getCurrent().getView(), address);
		listingService.goTo(loc, true);
	}

	void goToAddress(Address address) {
		DebuggerListingService listingService = getTool().getService(typeof(DebuggerListingService));
		if (listingService == null) {
			return;
		}
		goToAddress(listingService, address);
	}

	void goToRange(AddressRange range) {
		DebuggerListingService listingService = getTool().getService(typeof(DebuggerListingService));
		if (listingService == null) {
			return;
		}
		listingService.setCurrentSelection(
			new ProgramSelection(range.getMinAddress(), range.getMaxAddress()));
		goToAddress(listingService, range.getMinAddress());
	}

	bool performElementCellDefaultAction(JTable table) {
		int row = table.getSelectedRow();
		int col = table.getSelectedColumn();
		object cellValue = table.getValueAt(row, col);
		if (cellValue is ValueProperty<object> property) {
			object propValue = property.getValue();
			if (performDefaultAction(propValue)) {
				return true;
			}
		}
		return false;
	}

	bool performValueRowDefaultAction(ValueRow row) {
		if (row == null) {
			return false;
		}
		return performDefaultAction(row.getValue());
	}

	bool performPathRowDefaultAction(PathRow row) {
		if (row == null) {
			return false;
		}
		return performDefaultAction(row.getValue());
	}

	bool performDefaultAction(TraceObjectValue value) {
		if (value == null) {
			return false;
		}
		return performDefaultAction(value.getValue());
	}

	bool performDefaultAction(TraceObject @object) {
		Set<Class<TraceObjectInterface>> interfaces =
			@object.getSchema().getInterfaces();
		if (interfaces.contains(typeof(TraceActivatable))) {
			activatePath(@object.getCanonicalPath());
			return true;
		}
		/**
		 * Should I check aliveAndPresent() here? If I do, behavior changes when target is dead,
		 * which might be unexpected.
		 */
		if (interfaces.contains(typeof(TraceTogglable))) {
			toggleObject(@object);
			return true;
		}
		long snap = getCurrent().getSnap();
		TraceObjectValue valAddress = @object.getAttribute(snap, "_address");
		if (valAddress != null && valAddress.getValue() is Address address) {
			goToAddress(address);
			return true;
		}
		TraceObjectValue valRange = @object.getAttribute(snap, "_range");
		if (valRange != null && valRange.getValue() is AddressRange range) {
			goToRange(range);
			return true;
		}
		return false;
	}

	bool performDefaultAction(object value) {
		if (value is Address address) {
			goToAddress(address);
			return true;
		}
		if (value is AddressRange range) {
			goToRange(range);
			return true;
		}
		if (value is TraceObject @object) {
			return performDefaultAction(@object);
		}
		return false;
	}

}
